  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C04"],
      "claim": "Hydroxysafflor yellow A reached 1026 ng/g in rat brain in a tissue distribution study, directly demonstrating BBB permeation; high assay-transfer supports meaningful CNS access for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "Picroside-I rapidly penetrated the BBB and was detected in rat brain tissue, providing direct evidence of CNS access after systemic administration.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "Scandoside methyl ester was detected in rat brain microdialysates and tissue homogenates, confirming BBB passage for a structurally related natural product.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Deacetyl asperulosidic acid methyl ester was detected in rat brain microdialysates and tissue homogenates, further supporting BBB permeation in this chemical space.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "The prodrug (5R,6R)-BMAZT achieved a brain AUC of 55.7 %ID·min/g in mice, showing substantial brain entry after systemic dosing.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "Uridine crosses the BBB and is detected in brain areas shortly after intravenous injection, supporting transporter-mediated CNS access relevant to the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "Laudanosine was detected in cat CSF, demonstrating that a moderately lipophilic small molecule can cross the BBB into the CNS compartment.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "Dehydroascorbic acid is actively transported across the BBB by GLUT1 with significant brain accumulation, showing that transporter-mediated uptake can confer meaningful CNS exposure.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All high-transfer experimental records demonstrate BBB permeation or meaningful brain exposure across diverse chemotypes; combined with the query's small-molecule features, the evidence supports meaningful CNS access.",
  "evidence_gaps": [
    "No direct triptolide-specific brain/plasma or CSF measurement is included; prediction relies on high-transferability analogues.",
    "Efflux liability for the query is not directly assessed, though meaningful access can tolerate some efflux."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

